const USAGE_SHORT: &str = "Usage: executable [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]";
const USAGE_NOOPTS: &str = "Usage: executable <INPUT_FOLDER> [OUTPUT_FOLDER]";

#[derive(Default, Debug)]
struct Args {
    verbose: u8,
    watch: bool,
    serve: bool,
    bind: Option<String>,
    config: Option<String>,
    init_templates: bool,
    start_theme: Option<String>,
    set_theme: Option<String>,
    generate_config: bool,
    init_site: bool,
    force: bool,
    shortcodes: bool,
    show_urls: bool,
    new: Option<String>,
    edit: bool,
    as_page: bool,
    tags: Option<String>,
    name: Option<String>,
    tagline: Option<String>,
    url: Option<String>,
    https: Option<bool>,
    footer: Option<String>,
    language: Option<String>,
    pagination: Option<u32>,
    enable_search: Option<bool>,
    enable_related_content: Option<bool>,
    content_path: Option<String>,
    templates_path: Option<String>,
    static_path: Option<String>,
    media_path: Option<String>,
    default_date_format: Option<String>,
    colorscheme: Option<String>,
    toc: Option<bool>,
    json_feed: Option<bool>,
    show_next_prev_links: Option<bool>,
    publish_md: Option<bool>,
    source_repository: Option<String>,
    image_provider: Option<String>,
    theme: Option<String>,
    build_sitemap: Option<bool>,
    publish_urls_json: Option<bool>,
    enable_shortcodes: Option<bool>,
    shortcode_pattern: Option<String>,
    skip_image_resize: Option<bool>,

    input_folder: Option<String>,
    output_folder: Option<String>,
}

fn parse_bool(v: &str) -> Option<bool> {
    match v {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn err_unexpected(arg: &str) -> ExitCode {
    eprintln!("error: unexpected argument '{}' found", arg);
    eprintln!();
    eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
    eprintln!();
    eprintln!("{}", USAGE_SHORT);
    eprintln!();
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

fn err_missing_value(arg: &str) -> ExitCode {
    eprintln!("error: a value is required for '{}' but none was supplied", arg);
    eprintln!();
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

fn err_missing_required() -> ExitCode {
    eprintln!("error: the following required arguments were not provided:");
    eprintln!("  <INPUT_FOLDER>");
    eprintln!();
    eprintln!("{}", USAGE_NOOPTS);
    eprintln!();
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

fn parse_args(argv: Vec<String>) -> Result<Args, ExitCode> {
    let mut args = Args::default();
    let mut positional: Vec<String> = Vec::new();
    let mut it = argv.into_iter().skip(1).peekable();
    let mut after_ddash = false;

    while let Some(a) = it.next() {
        if after_ddash {
            positional.push(a);
            continue;
        }
        if a == "--" {
            after_ddash = true;
            continue;
        }
        if a == "-h" || a == "--help" {
            print!("{}", HELP_TEXT);
            return Err(ExitCode::from(0));
        }
        if a == "-V" || a == "--version" {
            println!("{}", VERSION);
            return Err(ExitCode::from(0));
        }
        // long options with =
        if let Some(rest) = a.strip_prefix("--") {
            let (name, val_inline) = match rest.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (rest.to_string(), None),
            };
            let needs_value = matches!(name.as_str(),
                "bind" | "config" | "start-theme" | "set-theme" | "new" | "name" | "tagline" |
                "url" | "https" | "footer" | "language" | "pagination" | "enable-search" |
                "enable-related-content" | "content-path" | "templates-path" | "static-path" |
                "media-path" | "default-date-format" | "colorscheme" | "toc" | "json-feed" |
                "show-next-prev-links" | "publish-md" | "source-repository" | "image-provider" |
                "theme" | "build-sitemap" | "publish-urls-json" | "enable-shortcodes" |
                "shortcode-pattern" | "skip-image-resize"
            );
            let val: Option<String> = if needs_value {
                if let Some(v) = val_inline {
                    Some(v)
                } else if let Some(v) = it.next() {
                    Some(v)
                } else {
                    return Err(err_missing_value(&format!("--{}", name)));
                }
            } else {
                if val_inline.is_some() {
                    return Err(err_unexpected(&a));
                }
                None
            };
            match name.as_str() {
                "verbose" => args.verbose = args.verbose.saturating_add(1),
                "watch" => args.watch = true,
                "serve" => args.serve = true,
                "bind" => args.bind = val,
                "config" => args.config = val,
                "init-templates" => args.init_templates = true,
                "start-theme" => args.start_theme = val,
                "set-theme" => args.set_theme = val,
                "generate-config" => args.generate_config = true,
                "init-site" => args.init_site = true,
                "force" => args.force = true,
                "shortcodes" => args.shortcodes = true,
                "show-urls" => args.show_urls = true,
                "new" => args.new = val,
                "name" => args.name = val,
                "tagline" => args.tagline = val,
                "url" => args.url = val,
                "https" => args.https = val.and_then(|v| parse_bool(&v)),
                "footer" => args.footer = val,
                "language" => args.language = val,
                "pagination" => args.pagination = val.and_then(|v| v.parse().ok()),
                "enable-search" => args.enable_search = val.and_then(|v| parse_bool(&v)),
                "enable-related-content" => args.enable_related_content = val.and_then(|v| parse_bool(&v)),
                "content-path" => args.content_path = val,
                "templates-path" => args.templates_path = val,
                "static-path" => args.static_path = val,
                "media-path" => args.media_path = val,
                "default-date-format" => args.default_date_format = val,
                "colorscheme" => args.colorscheme = val,
                "toc" => args.toc = val.and_then(|v| parse_bool(&v)),
                "json-feed" => args.json_feed = val.and_then(|v| parse_bool(&v)),
                "show-next-prev-links" => args.show_next_prev_links = val.and_then(|v| parse_bool(&v)),
                "publish-md" => args.publish_md = val.and_then(|v| parse_bool(&v)),
                "source-repository" => args.source_repository = val,
                "image-provider" => args.image_provider = val,
                "theme" => args.theme = val,
                "build-sitemap" => args.build_sitemap = val.and_then(|v| parse_bool(&v)),
                "publish-urls-json" => args.publish_urls_json = val.and_then(|v| parse_bool(&v)),
                "enable-shortcodes" => args.enable_shortcodes = val.and_then(|v| parse_bool(&v)),
                "shortcode-pattern" => args.shortcode_pattern = val,
                "skip-image-resize" => args.skip_image_resize = val.and_then(|v| parse_bool(&v)),
                _ => return Err(err_unexpected(&a)),
            }
            continue;
        }
        if let Some(rest) = a.strip_prefix('-') {
            if rest.is_empty() {
                positional.push(a);
                continue;
            }
            // handle short clusters like -vv etc
            let mut chars = rest.chars().peekable();
            while let Some(c) = chars.next() {
                match c {
                    'v' => args.verbose = args.verbose.saturating_add(1),
                    'w' => args.watch = true,
                    'e' => args.edit = true,
                    'p' => args.as_page = true,
                    'h' => {
                        print!("{}", HELP_TEXT);
                        return Err(ExitCode::from(0));
                    }
                    'V' => {
                        println!("{}", VERSION);
                        return Err(ExitCode::from(0));
                    }
                    'c' => {
                        let rest_str: String = chars.clone().collect();
                        let val = if !rest_str.is_empty() {
                            // consume remaining
                            for _ in 0..rest_str.len() { chars.next(); }
                            rest_str
                        } else if let Some(v) = it.next() {
                            v
                        } else {
                            return Err(err_missing_value("-c"));
                        };
                        args.config = Some(val);
                    }
                    't' => {
                        let rest_str: String = chars.clone().collect();
                        let val = if !rest_str.is_empty() {
                            for _ in 0..rest_str.len() { chars.next(); }
                            rest_str
                        } else if let Some(v) = it.next() {
                            v
                        } else {
                            return Err(err_missing_value("-t"));
                        };
                        args.tags = Some(val);
                    }
                    _ => return Err(err_unexpected(&a)),
                }
            }
            continue;
        }
        positional.push(a);
    }

    if positional.is_empty() {
        // Some subcommands might not need input folder? no, all do.
        return Err(err_missing_required());
    }
    args.input_folder = Some(positional[0].clone());
    if positional.len() >= 2 {
        args.output_folder = Some(positional[1].clone());
    }
    if positional.len() > 2 {
        return Err(err_unexpected(&positional[2]));
    }
    Ok(args)
}

fn log_err(msg: &str) {
    let ts = current_timestamp_rfc3339();
    eprintln!("[{}Z ERROR marmite] {}", ts, msg);
}

fn log_info(module: &str, msg: &str) {
    let ts = current_timestamp_rfc3339();
    eprintln!("[{}Z INFO  {}] {}", ts, module, msg);
}

fn current_timestamp_rfc3339() -> String {
    // Format: YYYY-MM-DDTHH:MM:SS
    use std::time::{SystemTime, UNIX_EPOCH};
    let d = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = d.as_secs() as i64;
    let (y, mo, da, h, mi, se) = epoch_to_ymdhms(secs);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, mo, da, h, mi, se)
}

fn epoch_to_ymdhms(secs: i64) -> (i32, u32, u32, u32, u32, u32) {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let h = (rem / 3600) as u32;
    let mi = ((rem % 3600) / 60) as u32;
    let se = (rem % 60) as u32;
    // Days since 1970-01-01
    let mut y = 1970i32;
    let mut d = days as i64;
    loop {
        let leap = is_leap(y);
        let year_days = if leap { 366 } else { 365 };
        if d >= year_days {
            d -= year_days;
            y += 1;
        } else if d < 0 {
            y -= 1;
            let leap_p = is_leap(y);
            d += if leap_p { 366 } else { 365 };
        } else {
            break;
        }
    }
    let month_days = if is_leap(y) {
        [31,29,31,30,31,30,31,31,30,31,30,31]
    } else {
        [31,28,31,30,31,30,31,31,30,31,30,31]
    };
    let mut mo = 0;
    while mo < 12 && d >= month_days[mo] as i64 {
        d -= month_days[mo] as i64;
        mo += 1;
    }
    (y, (mo+1) as u32, (d+1) as u32, h, mi, se)
}

fn is_leap(y: i32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

