fn run_generate_config(input_folder: &Path) -> ExitCode {
    if !input_folder.exists() {
        log_err(&format!("Input folder does not exist: {:?}", input_folder));
        return ExitCode::from(1);
    }
    let path = input_folder.join("marmite.yaml");
    if let Err(e) = fs::write(&path, generate_config_yaml()) {
        log_err(&format!("Failed to write config: {}", e));
        return ExitCode::from(1);
    }
    log_info("marmite::config", &format!("Config file generated: {}", path.display()));
    ExitCode::from(0)
}

