fn build_site(input_folder: &Path, output_folder: &Path) -> ExitCode {
    if !input_folder.exists() {
        log_err(&format!("Input folder does not exist: {:?}", input_folder));
        return ExitCode::from(1);
    }
    if let Err(e) = fs::create_dir_all(output_folder) {
        log_err(&format!("Failed to create output folder: {}", e));
        return ExitCode::from(1);
    }
    // Collect markdown files
    let mut md_files: Vec<PathBuf> = Vec::new();
    if let Ok(entries) = fs::read_dir(input_folder) {
        for e in entries.flatten() {
            let p = e.path();
            if p.is_file() {
                if let Some(ext) = p.extension() {
                    if ext == "md" {
                        md_files.push(p);
                    }
                }
            }
        }
    }
    md_files.sort();

    // Write a simple index.html
    let mut index = String::new();
    index.push_str("<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<title>Home</title>\n</head>\n<body>\n<h1>Home</h1>\n<ul>\n");
    for p in &md_files {
        if let Some(stem) = p.file_stem().and_then(|s| s.to_str()) {
            index.push_str(&format!("<li><a href=\"{}.html\">{}</a></li>\n", stem, stem));
        }
    }
    index.push_str("</ul>\n</body>\n</html>\n");
    let _ = fs::write(output_folder.join("index.html"), index);

    for p in &md_files {
        let content = fs::read_to_string(p).unwrap_or_default();
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("page");
        let html = format!("<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<title>{}</title>\n</head>\n<body>\n<pre>{}</pre>\n</body>\n</html>\n", stem, html_escape(&content));
        let _ = fs::write(output_folder.join(format!("{}.html", stem)), html);
    }

    // sitemap.xml
    let mut sitemap = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");
    for p in &md_files {
        if let Some(stem) = p.file_stem().and_then(|s| s.to_str()) {
            sitemap.push_str(&format!("  <url>\n    <loc>/{}.html</loc>\n  </url>\n", stem));
        }
    }
    sitemap.push_str("  <url>\n    <loc>/index.html</loc>\n  </url>\n</urlset>");
    let _ = fs::write(output_folder.join("sitemap.xml"), sitemap);

    // robots.txt
    let _ = fs::write(output_folder.join("robots.txt"), "User-agent: Mediapartners-Google\nDisallow:\n\nUser-agent: *\nAllow: /\n");

    // static folder
    let _ = fs::create_dir_all(output_folder.join("static"));

    println!("Site generated at {}/", output_folder.display());
    ExitCode::from(0)
}

fn html_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            _ => out.push(c),
        }
    }
    out
}

fn main() -> ExitCode {
    let _ = std::io::stdout().flush();
    let args: Vec<String> = env::args().collect();
    let parsed = match parse_args(args) {
        Ok(a) => a,
        Err(code) => return code,
    };

    let input = match parsed.input_folder {
        Some(ref p) => PathBuf::from(p),
        None => return err_missing_required(),
    };

    if parsed.generate_config {
        return run_generate_config(&input);
    }
    if parsed.shortcodes {
        if !input.exists() {
            log_err(&format!("Input folder does not exist: {:?}", input));
            return ExitCode::from(1);
        }
        return run_shortcodes();
    }

    let output = match parsed.output_folder {
        Some(ref p) => PathBuf::from(p),
        None => input.join("site"),
    };

    build_site(&input, &output)
}
